package com.staywise.hotel.controller;
import com.staywise.hotel.model.*;import com.staywise.hotel.repository.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;
@RestController @RequestMapping("/api") @CrossOrigin(origins="*") public class HotelController {
 private final HotelRepository hotels;private final BookingRepository bookings;public HotelController(HotelRepository h,BookingRepository b){hotels=h;bookings=b;}
 @GetMapping("/hotels") public List<Hotel> hotels(@RequestParam(required=false,defaultValue="") String city){return city.isBlank()?hotels.findAll():hotels.findByCityContainingIgnoreCase(city);}
 @GetMapping("/hotels/{id}") public ResponseEntity<Hotel> hotel(@PathVariable Long id){return hotels.findById(id).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());}
 public record BookingRequest(Long hotelId,String guestName,String email,int guests,String checkIn,String checkOut){}
 @PostMapping("/bookings") public ResponseEntity<?> book(@RequestBody BookingRequest q){if(q.guestName()==null||q.guestName().isBlank()||q.email()==null||!q.email().contains("@")||q.guests()<1)return ResponseEntity.badRequest().body(Map.of("error","Please provide valid guest details."));Hotel h=hotels.findById(q.hotelId()).orElse(null);if(h==null)return ResponseEntity.badRequest().body(Map.of("error","Hotel not found."));try{LocalDate in=LocalDate.parse(q.checkIn()),out=LocalDate.parse(q.checkOut());long nights=ChronoUnit.DAYS.between(in,out);if(in.isBefore(LocalDate.now())||nights<1)return ResponseEntity.badRequest().body(Map.of("error","Choose valid future dates; checkout must be after check-in."));if(h.availableRooms<1)return ResponseEntity.badRequest().body(Map.of("error","No rooms currently available."));Booking b=new Booking();b.hotel=h;b.guestName=q.guestName().trim();b.email=q.email().trim();b.guests=q.guests();b.checkIn=in;b.checkOut=out;b.totalPrice=nights*h.pricePerNight;h.availableRooms--;hotels.save(h);return ResponseEntity.ok(bookings.save(b));}catch(Exception e){return ResponseEntity.badRequest().body(Map.of("error","Dates must use YYYY-MM-DD format."));}}
 @GetMapping("/bookings") public List<Booking> myBookings(@RequestParam String email){return bookings.findByEmailIgnoreCaseOrderByIdDesc(email);}
 @DeleteMapping("/bookings/{id}") public ResponseEntity<?> cancel(@PathVariable Long id,@RequestParam String email){return bookings.findById(id).map(b->{if(!b.email.equalsIgnoreCase(email))return ResponseEntity.status(403).body(Map.of("error","This booking belongs to another guest."));if(b.status.equals("CANCELLED"))return ResponseEntity.ok(b);b.status="CANCELLED";b.hotel.availableRooms++;hotels.save(b.hotel);return ResponseEntity.ok(bookings.save(b));}).orElse(ResponseEntity.notFound().build());}
}
